# Compute closure events for given group in interval [18400, 36212]
seed = [61,63,86,114,140,188,251,329,339,359,517,656]
start, end = 18400, 36212
# Build interactions list within window
window_events = [(u,v,t) for (u,v,t) in events if start <= t <= end]
# For ease, consider any interaction between node and third node counts (either direction)
# For each seed node, collect times interacting with each other node
from collections import defaultdict
node_contact_times = defaultdict(list)  # (seed,node) -> times
for (u,v,t) in window_events:
    if u in seed:
        node_contact_times[(u,v)].append(t)
    if v in seed:
        node_contact_times[(v,u)].append(t)
# Also collect interactions between seed pairs
pair_interactions = defaultdict(list)  # (a,b) directed? we consider any direction
for (u,v,t) in window_events:
    if u in seed and v in seed:
        pair = tuple(sorted((u,v)))
        pair_interactions[pair].append((u,v,t))
# For any pair a,b in seed, find third node x where both have interactions with x
closures = []
seed_set = set(seed)
for i in range(len(seed)):
    for j in range(i+1,len(seed)):
        a = seed[i]; b = seed[j]
        # find third nodes
        # collect all interactions of a with x and b with x
        contacts_a = defaultdict(list)
        contacts_b = defaultdict(list)
        for (u,v,t) in window_events:
            if u==a:
                contacts_a[v].append(t)
            if v==a:
                contacts_a[u].append(t)
            if u==b:
                contacts_b[v].append(t)
            if v==b:
                contacts_b[u].append(t)
        common_x = set(contacts_a.keys()) & set(contacts_b.keys())
        for x in common_x:
            if x in (a,b):
                continue
            for ta in contacts_a[x]:
                for tb in contacts_b[x]:
                    est = max(ta,tb)
                    # find interaction between a and b within 800 after est
                    # consider any direction
                    found = []
                    for (u,v,t) in window_events:
                        if t >= est and t <= est+800:
                            if (u==a and v==b) or (u==b and v==a):
                                found.append((u,v,t))
                    for f in found:
                        closures.append({'a':a,'b':b,'x':x,'ta':ta,'tb':tb,'est':est,'close_event':f})
# Sort closures by close_event time
closures.sort(key=lambda c: c['close_event'][2])
print(len(closures))
for c in closures:
    print(c)

# Re-evaluate closures: for each seed pair interaction, check for common contact events earlier within 800
seed = [61,63,86,114,140,188,251,329,339,359,517,656]
start, end = 18400, 36212
we = [(u,v,t) for (u,v,t) in events if start <= t <= end]
# For quick lookup, events by node (both as u or v)
from collections import defaultdict
events_by_node = defaultdict(list)
for (u,v,t) in we:
    events_by_node[u].append((v,t,'out'))
    events_by_node[v].append((u,t,'in'))
for n in events_by_node:
    events_by_node[n].sort(key=lambda x: x[1])

closures = []
for (u,v,t) in we:
    if u in seed and v in seed:
        pair_time = t
        a,b = u,v
        # look for x such that a interacted with x at ta and b interacted with x at tb with est = max(ta,tb)
        # and est <= pair_time <= est+800
        for x in set([n for (n,_,_) in events_by_node[a]]) & set([n for (n,_,_) in events_by_node[b]]):
            if x in (a,b):
                continue
            # find interactions times
            times_a = [tt for (n,tt,_dir) in events_by_node[a] if n==x]
            times_b = [tt for (n,tt,_dir) in events_by_node[b] if n==x]
            for ta in times_a:
                for tb in times_b:
                    est = max(ta,tb)
                    if est <= pair_time <= est+800:
                        closures.append({'a':a,'b':b,'x':x,'ta':ta,'tb':tb,'est':est,'pair_event':(u,v,t)})

print(len(closures))
